import { GameScene } from "../modules";

export const createAlphaTween = (
  scene: GameScene,
  target: {
    alpha: number;
    setAlpha: (v: number) => any;
  },
  type: "show" | "hide",
) => {
  const defaultAlpha = type === "hide" ? 1 : 0,
    finalAlpha = type === "show" ? 0 : 1;

  const destroyTween = scene.tweens.add({
    targets: { alpha: defaultAlpha },
    alpha: finalAlpha,
    duration: 1000,
    onUpdate: (event) => {
      const current = event.targets[0] as { alpha?: number };
      if (current?.alpha) target.setAlpha(current.alpha);
    },
  });

  return destroyTween;
};
